def flatten_depth(lst, depth):
    if depth <= 0:
        return list(lst)
    result = []
    for item in lst:
        if isinstance(item, list):
            if depth == 1:
                result.append(item)
            else:
                result.extend(flatten_depth(item, depth - 1))
        else:
            result.append(item)
    return result
